INSERT INTO feature VALUES('loops','effects','Loops with break and continue',NULL,'implemented','ordinary',NULL,'`loop` and `while` lower into the partial fixpoint, `break` and `continue` as direct cuts; a function holding one states `Partial` in its row, unless every pass of the loop acts on an endpoint it threads before it runs again. Such a loop is a demonic iteration over its protocol: each pass is one step, and the loop need not exit. The kernel has no image of such a loop (#6099): the bridge declines it by name, and the report states that the declaration has no kernel image.','surface-lowering core-sequent core-checker surface-dispatcher','corpus/surface/control-flow.gandr corpus/model/sessions/endpoint-loop.gandr corpus/pathological/sessions/endpoint-loop.gandr','corpus/surface/control-flow.gandr',NULL);
